package monitor

import (
	"gpuworks.ai/gpuworks/internal/server/tsdb"
)

// This file computes Window's proxy-accounting-derived fields
// (RequestsPerSec, ErrRate5xx/429/Asleep, InflightAvg/InflightLast/
// InflightMax, ProxyRequestsDelta/ClientErrorsDelta/ServerErrorsDelta) from a
// deployment's already-scoped WindowSeries.ProxyRequestsTotal/ProxyInflight
// (see proxy/accounting.go and the phase2 metrics contract's Proxy section).
// Unlike the per-instance infer metrics, proxy series are always
// deployment-labeled (node="server", generated by the server itself, no
// per-instance/old-agent fallback concept) - WindowSeries already carries
// only this deployment's own series, filtered by GroupWindowSeries/
// FetchWindowSeries.

// errClass5xx, errClass429 and errClassAsleep mirror proxy/accounting.go's
// reqClass values without importing that package (a leaf package cycle:
// proxy already imports tsdb and would gain nothing from also depending on
// monitor, so the four class strings are simply duplicated here as the
// wire's fixed vocabulary - proxy/accounting_test.go and this package's own
// tests both pin the exact strings, so a drift between the two would fail
// loudly rather than silently).
const (
	errClass4xx    = "4xx"
	errClass5xx    = "5xx"
	errClass429    = "429"
	errClassAsleep = "asleep_503"
)

// computeProxySignals fills RequestsPerSec, ErrRate4xx/5xx/429/Asleep,
// InflightAvg/InflightLast/InflightMax and the exact
// ProxyRequestsDelta/ClientErrorsDelta/ServerErrorsDelta counter deltas the
// alignment row needs (see Window's doc comments for why these are kept
// separate from the rate-based fields above).
func computeProxySignals(w *Window, series WindowSeries) {
	computeInflight(w, series.ProxyInflight)

	if len(series.ProxyRequestsTotal) == 0 {
		return
	}
	byClass := map[string][]tsdb.Series{}
	for _, s := range series.ProxyRequestsTotal {
		byClass[s.Labels["class"]] = append(byClass[s.Labels["class"]], s)
	}

	rateByClass := map[string]tsdb.Series{}
	var totalRates []tsdb.Series
	for class, ss := range byClass {
		summed := SumBy(Rate(ss), "")
		if len(summed) == 0 {
			continue
		}
		rateByClass[class] = summed[0]
		totalRates = append(totalRates, summed[0])
	}
	totalCombined := SumBy(totalRates, "")
	if len(totalCombined) == 0 || len(totalCombined[0].Points) == 0 {
		return
	}
	total := totalCombined[0]

	w.HasRequestRate = true
	w.RequestsPerSec = Mean(Values(total))

	w.HasErrRate = true
	w.ErrRate4xx = errShare(rateByClass[errClass4xx], total)
	w.ErrRate5xx = errShare(rateByClass[errClass5xx], total)
	w.ErrRate429 = errShare(rateByClass[errClass429], total)
	w.ErrRateAsleep = errShare(rateByClass[errClassAsleep], total)

	w.ProxyRequestsDelta = SumSeriesDelta(series.ProxyRequestsTotal)
	w.ClientErrorsDelta = SumSeriesDelta(byClass[errClass4xx]) + SumSeriesDelta(byClass[errClass429])
	w.ServerErrorsDelta = SumSeriesDelta(byClass[errClass5xx]) + SumSeriesDelta(byClass[errClassAsleep])
}

// errShare divides classRate by total at every bucket both have a point for
// (ratioSeries), then reduces that ratio series to its window average.
func errShare(classRate, total tsdb.Series) float64 {
	ratio := ratioSeries(classRate, total)
	if len(ratio.Points) == 0 {
		return 0
	}
	return Mean(Values(ratio))
}

// ratioSeries divides numerator by denominator at every timestamp
// denominator has a point for, skipping a bucket entirely when denominator
// is missing it or is <= 0 - a gap excludes the bucket rather than
// manufacturing a false value, so a momentary lull in total traffic can
// never look like a spurious 0% or divide-by-zero error rate.
func ratioSeries(numerator, denominator tsdb.Series) tsdb.Series {
	denomByTS := make(map[int64]float64, len(denominator.Points))
	for _, p := range denominator.Points {
		denomByTS[p.TimeMS] = p.Value
	}
	points := make([]tsdb.Point, 0, len(numerator.Points))
	for _, p := range numerator.Points {
		d, ok := denomByTS[p.TimeMS]
		if !ok || d <= 0 {
			continue
		}
		points = append(points, tsdb.Point{TimeMS: p.TimeMS, Value: p.Value / d})
	}
	return tsdb.Series{Points: points}
}

func computeInflight(w *Window, series []tsdb.Series) {
	if len(series) == 0 {
		return
	}
	avg := AvgBy(series, "")
	if len(avg) == 0 || len(avg[0].Points) == 0 {
		return
	}
	values := Values(avg[0])
	w.HasInflight = true
	w.InflightAvg = Mean(values)
	w.InflightLast = values[len(values)-1]
	w.InflightMax = MaxOf(values)
}
